def choose_move(observation):
    width = observation.get('width', 0)
    height = observation.get('height', 0)
    own_pos = observation.get('players', {}).get('own', {}).get('pos', [0, 0])
    resources = observation.get('resources', [])
    enemies = observation.get('players', {}).get('enemies', [])
    territory_control = observation.get('territory', {}).get('owner', [])
    x, y = own_pos

    def in_bounds(nx, ny):
        return 0 <= nx < width and 0 <= ny < height

    # Helper: get the closest resource
    def closest_resource():
        min_dist = float('inf')
        target = None
        for r in resources:
            rx, ry = r
            dist = abs(rx - x) + abs(ry - y)
            if dist < min_dist:
                min_dist = dist
                target = (rx, ry)
        return target, min_dist

    # Helper: get the closest enemy
    def closest_enemy():
        min_dist = float('inf')
        target = None
        for enemy in enemies:
            ex, ey = enemy.get('pos', [0, 0])
            dist = abs(ex - x) + abs(ey - y)
            if dist < min_dist:
                min_dist = dist
                target = (ex, ey)
        return target, min_dist

    # Helper: get the closest territory of interest
    def closest_territory():
        min_dist = float('inf')
        target_idx = None
        for idx, owner in enumerate(territory_control):
            if owner != 'own':
                tx = idx % width
                ty = idx // width
                dist = abs(tx - x) + abs(ty - y)
                if dist < min_dist:
                    min_dist = dist
                    target_idx = (tx, ty)
        return target_idx, min_dist

    # Move towards a target point
    def move_towards(target):
        if target is None:
            return [0,0]
        tx, ty = target
        dx = dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        # Prefer moving along the axis with larger distance
        if abs(tx - x) > abs(ty - y):
            return [dx, 0]
        elif abs(ty - y) > 0:
            return [0, dy]
        else:
            return [dx, dy]

    # 1. Resource collection when adjacent
    for r in resources:
        rx, ry = r
        dist = abs(rx - x) + abs(ry - y)
        if dist == 1:
            return [rx - x, ry - y]
    # Otherwise, move towards the nearest resource
    resource_pos, res_dist = closest_resource()
    if res_dist > 1:
        move_res = move_towards(resource_pos)
        if in_bounds(x + move_res[0], y + move_res[1]):
            return move_res

    # 2. Pursuit/evasion: move towards nearest enemy if adjacent
    for enemy in enemies:
        ex, ey = enemy.get('pos', [0, 0])
        dist = abs(ex - x) + abs(ey - y)
        if dist == 1:
            return [ex - x, ey - y]
    if enemies:
        enemy_pos, enemy_dist = closest_enemy()
        if enemy_dist > 1:
            move_enemy = move_towards(enemy_pos)
            if in_bounds(x + move_enemy[0], y + move_enemy[1]):
                return move_enemy

    # 3. Territory control: move towards unowned/human territory
    terr_pos, terr_dist = closest_territory()
    if terr_pos is not None and terr_dist > 0:
        move_terr = move_towards(terr_pos)
        if in_bounds(x + move_terr[0], y + move_terr[1]):
            return move_terr

    # 4. No active cues: stay put
    return [0, 0]

